def fn_11398(x: int) -> bool:
    "numbers n where n mod 6 is 0, 4, or 3"
    return x % 6 in {0, 3, 4}

@register(11399)
def fn_11399(x: int) -> bool:
    "numbers whose digits sum to a value between 5 and 12 inclusive"
    return 5 <= _digit_sum(x) <= 12

@register(11400)
def fn_11400(x: int) -> bool:
    "numbers between 51 and 61 inclusive"
    return 51 <= x <= 61

@register(11401)
def fn_11401(x: int) -> bool:
    "numbers whose first digit is 5 or 6"
    return str(x).startswith('5') or str(x).startswith('6')

@register(11402)
def fn_11402(x: int) -> bool:
    "numbers whose digits are both odd or both even"
    return 10 <= x <= 99 and x // 10 % 2 == x % 2

@register(11403)
def fn_11403(x: int) -> bool:
    "numbers starting with 8 or 9"
    return str(x).startswith('8') or str(x).startswith('9')

@register(11404)
def fn_11404(x: int) -> bool:
    "numbers whose digits are in {1, 3, 6, 8, 9}"
    return all(int(d) in {1, 3, 6, 8, 9} for d in str(abs(x)))

